CREATE TABLE portal_users (id BIGINT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(150) NOT NULL, age INT NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(25) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'STUDENT', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE portal_courses (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(180) NOT NULL, description TEXT, monthly_price DECIMAL(12,2) NOT NULL DEFAULT 0, yearly_price DECIMAL(12,2) NOT NULL DEFAULT 0, meet_url VARCHAR(500), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE portal_enrollments (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, course_id BIGINT NOT NULL, plan VARCHAR(12) NOT NULL, renewal_mode VARCHAR(12) NOT NULL, status VARCHAR(20) NOT NULL, expires_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES portal_users(id), FOREIGN KEY (course_id) REFERENCES portal_courses(id));
CREATE TABLE portal_payments (id BIGINT PRIMARY KEY AUTO_INCREMENT, enrollment_id BIGINT NOT NULL, provider VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL, amount DECIMAL(12,2) NOT NULL, reference_code VARCHAR(80) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(enrollment_id) REFERENCES portal_enrollments(id));
CREATE TABLE portal_announcements (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(200) NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE portal_attendance (id BIGINT PRIMARY KEY AUTO_INCREMENT, enrollment_id BIGINT NOT NULL, class_date DATE NOT NULL, status VARCHAR(20) NOT NULL, UNIQUE KEY unique_attendance(enrollment_id,class_date), FOREIGN KEY(enrollment_id) REFERENCES portal_enrollments(id));
